//! 📽️ Admitted Presentation owners and explicit reuse of persisted Document block types.
use super::{SemioPresentationSnapshot,SlideMaster,SlideLayout,Slide,SlideShape,SlideFrame,SlidePictureImage,SlideTableRow,SlideTableCell,PlaceholderKind,SemioPoint2,DocBlock,STDIO_SEMIOPRESENTATION_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding as native;
use crate::standards::v1::subsets::document::schema::snapshot::native_decoding as document_native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(super) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioPresentationSnapshot,String>{native::decode(payload,STDIO_SEMIOPRESENTATION_DOCUMENT_SCHEMA,control,binary,document)}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,String>{reader.read_f64_le().map_err(|e|e.to_string())}
fn frame_binary(reader:&mut store::ByteReader<'_>)->Result<SlideFrame,String>{Ok(SlideFrame{origin:SemioPoint2{x:f64(reader)?,y:f64(reader)?},width:f64(reader)?,height:f64(reader)?})}
fn option(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,String>{match reader.read_u8().map_err(|e|e.to_string())?{0=>Ok(None),1=>native::text(reader,control).map(Some),_=>Err("invalid Presentation native optional presence".into())}}
fn placeholder_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<PlaceholderKind,String>{Ok(match reader.read_u8().map_err(|e|e.to_string())?{0=>PlaceholderKind::Title,1=>PlaceholderKind::Subtitle,2=>PlaceholderKind::Body,3=>PlaceholderKind::Footer,4=>PlaceholderKind::SlideNumber,5=>PlaceholderKind::DateTime,6=>PlaceholderKind::Other{value:native::text(reader,control)?},_=>return Err("invalid Presentation native placeholder".into())})}
fn blocks_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<DocBlock>,String>{native::entities(entities,1,limits)?;native::binary_list(reader,control,limits,entities,|reader,control,entities|{let body=control.borrow_text(native::bytes(reader)?)?;document_native::block_text(body,control,limits,entities)})}
fn shape_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<SlideShape,String>{native::entities(entities,1,limits)?;let tag=reader.read_u8().map_err(|e|e.to_string())?;let frame=frame_binary(reader)?;Ok(match tag{
0=>SlideShape::TextBox{frame,blocks:blocks_binary(reader,control,limits,entities)?},1=>SlideShape::Picture{frame,image:SlidePictureImage{asset_id:native::text(reader,control)?,mime:native::text(reader,control)?,bytes:control.copy_bytes(native::bytes(reader)?)?}},
2=>{let rows=native::binary_list(reader,control,limits,entities,|reader,control,entities|{let cells=native::binary_list(reader,control,limits,entities,|reader,control,entities|Ok(SlideTableCell{blocks:blocks_binary(reader,control,limits,entities)?}))?;Ok(SlideTableRow{cells})})?;SlideShape::Table{frame,rows}},3=>SlideShape::Placeholder{frame,kind:placeholder_binary(reader,control)?},_=>return Err("invalid Presentation native shape".into())})}
fn shapes_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<SlideShape>,String>{native::binary_list(reader,control,limits,entities,|reader,control,entities|shape_binary(reader,control,limits,entities))}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioPresentationSnapshot,String>{let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|e.to_string())?!=1{return Err("unsupported Presentation native format".into())}let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::text(&mut reader,control)?;
let masters=native::Owned::new(native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|Ok(SlideMaster{id:native::text(reader,control)?,shapes:shapes_binary(reader,control,limits,entities)?}))?);
let layouts=native::Owned::new(native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|Ok(SlideLayout{id:native::text(reader,control)?,master_id:native::text(reader,control)?,shapes:shapes_binary(reader,control,limits,entities)?}))?);
let slides=native::Owned::new(native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let layout_id=option(reader,control)?;let shapes=native::Owned::new(shapes_binary(reader,control,limits,entities)?);let notes=blocks_binary(reader,control,limits,entities)?;Ok(Slide{id,layout_id,shapes:shapes.take(),notes})})?);if reader.remaining()!=0{return Err("Presentation native trailing bytes".into())}Ok(SemioPresentationSnapshot{schema,masters:masters.take(),layouts:layouts.take(),slides:slides.take()})}
fn optional_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,String>{if value=="[0]"{return Ok(None)}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err("invalid Presentation native optional presence".into())}native::hex_text(value,control).map(Some)}
fn number_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<f64,String>{control.scoped_stage(|control|{control.begin_stage(value.len())?;for _ in value.bytes(){control.step()?;}value.parse::<u64>().map(f64::from_bits).map_err(|_|"invalid Presentation native IEEE unsigned64 word".to_string())})}
fn frame_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SlideFrame,String>{let[origin,width,height]=native::record(value,control)?;let[x,y]=native::record(origin,control)?;Ok(SlideFrame{origin:SemioPoint2{x:number_text(x,control)?,y:number_text(y,control)?},width:number_text(width,control)?,height:number_text(height,control)?})}
fn placeholder_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<PlaceholderKind,String>{Ok(match value{"T"=>PlaceholderKind::Title,"S"=>PlaceholderKind::Subtitle,"B"=>PlaceholderKind::Body,"F"=>PlaceholderKind::Footer,"N"=>PlaceholderKind::SlideNumber,"D"=>PlaceholderKind::DateTime,_=>{let value=value.strip_prefix('O').ok_or("invalid Presentation native placeholder")?;let[value]=native::record(value,control)?;PlaceholderKind::Other{value:native::hex_text(value,control)?}}})}
fn shape_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<SlideShape,String>{native::entities(entities,1,limits)?;let(tag,value)=value.split_at_checked(1).ok_or("Presentation native shape tag missing")?;let[frame,value]=native::record(value,control)?;let frame=frame_text(frame,control)?;Ok(match tag{
"X"=>SlideShape::TextBox{frame,blocks:document_native::blocks_text(value,control,limits,entities)?},
"P"=>{let[asset_id,mime,bytes]=native::record(value,control)?;SlideShape::Picture{frame,image:SlidePictureImage{asset_id:native::hex_text(asset_id,control)?,mime:native::hex_text(mime,control)?,bytes:native::hex(bytes,control)?}}},
"T"=>{let rows=native::text_list(value,control,limits,entities,|value,control,entities|{let cells=native::text_list(value,control,limits,entities,|value,control,entities|Ok(SlideTableCell{blocks:document_native::blocks_text(value,control,limits,entities)?}))?;Ok(SlideTableRow{cells})})?;SlideShape::Table{frame,rows}},"H"=>SlideShape::Placeholder{frame,kind:placeholder_text(value,control)?},_=>return Err("invalid Presentation native shape".into())})}
fn shapes_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<Vec<SlideShape>,String>{native::text_list(value,control,limits,entities,|value,control,entities|shape_text(value,control,limits,entities))}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioPresentationSnapshot,String>{let mut entities=0;native::entities(&mut entities,1,limits)?;let fields=native::fields(body,["schema","masters","layouts","slides"],control)?;let schema=fields[0].ok_or("Presentation native schema missing")?;let masters=fields[1].unwrap_or("[]");let layouts=fields[2].unwrap_or("[]");let slides=fields[3].unwrap_or("[]");let schema=native::hex_text(schema,control)?;
let masters=native::Owned::new(native::text_list(masters,control,limits,&mut entities,|value,control,entities|{let[id,shapes]=native::record(value,control)?;Ok(SlideMaster{id:native::hex_text(id,control)?,shapes:shapes_text(shapes,control,limits,entities)?})})?);
let layouts=native::Owned::new(native::text_list(layouts,control,limits,&mut entities,|value,control,entities|{let[id,master_id,shapes]=native::record(value,control)?;Ok(SlideLayout{id:native::hex_text(id,control)?,master_id:native::hex_text(master_id,control)?,shapes:shapes_text(shapes,control,limits,entities)?})})?);
let slides=native::text_list(slides,control,limits,&mut entities,|value,control,entities|{let[id,layout_id,shapes,notes]=native::record(value,control)?;let id=native::hex_text(id,control)?;let layout_id=optional_text(layout_id,control)?;let shapes=native::Owned::new(shapes_text(shapes,control,limits,entities)?);let notes=document_native::blocks_text(notes,control,limits,entities)?;Ok(Slide{id,layout_id,shapes:shapes.take(),notes})})?;Ok(SemioPresentationSnapshot{schema,masters:masters.take(),layouts:layouts.take(),slides})}
